suppressMessages({library(dplyr);library(bundeslaendeR);library(tidyr)}); options(width=250, dplyr.print_max=500)
u <- readRDS("data/state_elections/final/state_unharm.rds")
bl <- as.data.frame(ltw_elections) %>% mutate(election_date=as.Date(election_date))
st <- c(BW="08",BY="09",BE="11",BB="12",HB="04",HH="02",HE="06",MV="13",NI="03",NW="05",RP="07",SL="10",SN="14",ST="15",SH="01",TH="16")
pm <- c(SSW="ssw",NPD="npd",DVU="dvu",Rep="rep",BIW="biw",Piraten="piraten",`FW-SH`="freie_wahler",`FW-SL`="freie_wahler",DiePartei="die_partei",Die_Partei="die_partei",`Die Tierschutzpartei`="tierschutz",Tierschutzpartei="tierschutz",DSU="dsu",ÖDP="oedp",Familie="familie",AfD="afd",Linke="linke_pds",WASG="wasg",Grüne="gruene",FDP="fdp",CDU="cdu",SPD="spd",CSU="csu")
cand <- bl %>% filter(election_date>=as.Date("1990-01-01"), party_vshare>=0.015, partyname_short %in% names(pm)) %>% mutate(state_gerda=st[state], col=pm[partyname_short])
agg <- u %>% group_by(state, election_date) %>% group_modify(~{vv<-sum(.x$valid_votes,na.rm=T); pc<-intersect(unique(pm),names(.x)); data.frame(col=pc, g=sapply(pc,function(p) if(all(is.na(.x[[p]]))) NA_real_ else sum(.x[[p]]*.x$valid_votes,na.rm=T)/vv), vv=vv)}) %>% ungroup()
m <- cand %>% inner_join(agg, by=c("state_gerda"="state","election_date","col")) 
m <- m %>% mutate(dev=100*(coalesce(g,0)-party_vshare), g_na=is.na(g))
cat("elections in bl >=1990 that GERDA unharm has:", n_distinct(m$state,m$election_date), "\n")
print(m %>% filter(abs(dev)>1) %>% select(state_gerda,election_date,partyname_short,col,gerda=g,bl=party_vshare,dev,vv) %>% arrange(desc(abs(dev))) %>% mutate(gerda=round(gerda,4),bl=round(bl,4),dev=round(dev,2)) %>% as.data.frame())
# also what about election dates in bl >=1990 with no GERDA rows
bd <- bl %>% distinct(state, election_date) %>% filter(election_date>=as.Date("1990-01-01")) %>% mutate(state_gerda=st[state]) %>% anti_join(u %>% distinct(state, election_date), by=c("state_gerda"="state","election_date"))
cat("\nbl elections >=1990 absent in unharm:\n"); print(as.data.frame(bd))
